import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    public static void main(String[] args) throws java.lang.Exception
    {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t--> 0) {
            int n = sc.nextInt();
            int total = 3 * n;
            long[] a = new long[total];

            for (int i = 0; i < total; i++) a[i] = sc.nextLong();

            Arrays.sort(a);

            for (int i = 0, j = total - 1; i < j; i++, j--) {
                long temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }

            long[] pref = new long[total + 1];

            for (int i = 0; i < total; i++)
                pref[i + 1] = pref[i] + a[i];

            long answer = 0;

            for (int j = 0; j <= n; j++) {
                int lo = 0, hi = n - j;

                while (lo < hi) {
                    int b = (lo + hi + 1) / 2;
                    int k = j + 2 * (b - 1);

                    int m = 3 * n - 2 * j - (b - 1);
                    long delta = a[k] + a[k + 1] - 3 * a[m - 1];

                    if (delta >= 0) lo = b;
                    else hi = b - 1;

                }

                int b = lo;
                int c = n - j - b;
                int end4 = j+ 2 * b, end3 = end4 + 3 * c;
                long current = 6 * pref[j] + 4 * (pref[end4] - pref[j]) + 3 * (pref[end3] - pref[end4]);
                answer = Math.max(answer, current);
            }
            System.out.println(answer);
        }
    }
}
